def calculate_Ai(a):
    N = len(a)
    A_i = 0
    for x in range(N):
        product = 1.0
        ax = a[x]
        for y in range(N):
            if x != y:
                ay = a[y]
                try:
                    term = (ax * ay - 1) / (ax - ay)
                    product *= term
                except ZeroDivisionError:
                    # Should not happen for distinct powers of 3
                    return "Error: Division by zero"
        A_i += product
    return A_i

# Case i=1 (N=2): a1=3, a2=9
